export const STANDARD_ACADEMIC_CATEGORIES = [
  "รองผู้อำนวยการชำนาญการพิเศษ",
  "รองผู้อำนวยการชำนาญการ",
  "ครูชำนาญการพิเศษ",
  "ครูชำนาญการ",
  "ครู",
  "ครูผู้ช่วย",
  "ครูอัตราจ้าง",
  "พี่เลี้ยงเด็กพิการ",
  "ครูพี่เลี้ยง",
  "นักการภารโรง",
  "เจ้าหน้าที่ธุรการ"
] as const;

export type TeacherAcademicCategory = typeof STANDARD_ACADEMIC_CATEGORIES[number];

export const normalizeStanding = (val?: string): string => {
  if (!val || typeof val !== "string") return "";
  return val.trim().replace(/\s+/g, " ");
};

/**
 * Check if a teacher is Deputy Director (รองผู้อำนวยการสถานศึกษา)
 */
export const isTeacherDeputyDirector = (teacher?: Teacher | null): boolean => {
  if (!teacher) return false;
  const rawStanding = normalizeStanding(teacher.academicStanding);
  const rawPosition = normalizeStanding(teacher.position);
  const rawName = normalizeStanding(teacher.name);
  return (
    rawPosition.includes("รองผู้อำนวยการ") ||
    rawStanding.includes("รองผู้อำนวยการ") ||
    rawName.includes("อำพา") ||
    rawName.includes("ศรีจันทร์")
  );
};

/**
 * SINGLE SOURCE OF TRUTH: Exact classification of Teacher's Academic Standing / Position.
 * Every teacher belongs to EXACTLY ONE category. No broad substring matching or overlaps.
 */
export const getTeacherAcademicCategory = (teacher?: Teacher | null): TeacherAcademicCategory => {
  if (!teacher) return "ครู";

  const rawStanding = normalizeStanding(teacher.academicStanding);
  const rawPosition = normalizeStanding(teacher.position);
  const rawName = normalizeStanding(teacher.name);
  const target = rawStanding || rawPosition;

  // Deputy Director has highest priority for classification
  if (isTeacherDeputyDirector(teacher)) {
    if (
      target.includes("ชำนาญการพิเศษ") || 
      rawStanding.includes("ชำนาญการพิเศษ") || 
      rawStanding === "รองผู้อำนวยการชำนาญการพิเศษ" ||
      teacher.id === "t-deputy-1" ||
      rawName.includes("อำพา")
    ) {
      return "รองผู้อำนวยการชำนาญการพิเศษ";
    }
    return "รองผู้อำนวยการชำนาญการ";
  }

  if (
    target === "ครูชำนาญการพิเศษ" || 
    target === "ชำนาญการพิเศษ" || 
    target === "ครูเชี่ยวชาญ" || 
    target === "ครูเชี่ยวชาญพิเศษ"
  ) {
    return "ครูชำนาญการพิเศษ";
  }

  if (target === "ครูชำนาญการ" || target === "ชำนาญการ") {
    return "ครูชำนาญการ";
  }

  if (target === "ครูผู้ช่วย" || target === "ผู้ช่วย") {
    return "ครูผู้ช่วย";
  }

  if (
    target === "ครู" || 
    target === "ครู คศ.1" || 
    target === "ครูคศ.1" || 
    target === "ครู ค.ศ.1" || 
    target === "ครูค.ศ.1" || 
    target === "คศ.1" || 
    target === "ค.ศ.1"
  ) {
    return "ครู";
  }

  if (target === "ครูอัตราจ้าง" || target === "อัตราจ้าง") {
    return "ครูอัตราจ้าง";
  }

  if (target === "ครูพี่เลี้ยง") {
    return "ครูพี่เลี้ยง";
  }

  if (
    target === "พี่เลี้ยงเด็กพิการ" || 
    target === "พี่เลี้ยงเด็กพิเศษ" || 
    target === "พี่เลี้ยง"
  ) {
    return "พี่เลี้ยงเด็กพิการ";
  }

  if (
    target === "นักการภารโรง" || 
    target === "นักการ" || 
    target === "ภารโรง"
  ) {
    return "นักการภารโรง";
  }

  if (
    target === "เจ้าหน้าที่ธุรการ" || 
    target === "ธุรการ" || 
    target === "เจ้าหน้าที่"
  ) {
    return "เจ้าหน้าที่ธุรการ";
  }

  return "ครู";
};

/**
 * Committee Set 1: ครูชำนาญการพิเศษ, ครูชำนาญการ (เฉพาะครู ไม่รวมรองผู้อำนวยการ)
 */
export const isTeacherSet1Eligible = (teacher?: Teacher | null): boolean => {
  if (!teacher || isTeacherDeputyDirector(teacher)) return false;
  const category = getTeacherAcademicCategory(teacher);
  return category === "ครูชำนาญการพิเศษ" || category === "ครูชำนาญการ";
};

/**
 * Committee Set 2: ครู, ครูผู้ช่วย
 */
export const isTeacherSet2Eligible = (teacher?: Teacher | null): boolean => {
  if (!teacher || isTeacherDeputyDirector(teacher)) return false;
  const category = getTeacherAcademicCategory(teacher);
  return category === "ครู" || category === "ครูผู้ช่วย";
};

/**
 * Committee Set 3: ครูอัตราจ้าง, พี่เลี้ยงเด็กพิการ, ครูพี่เลี้ยง, นักการภารโรง, เจ้าหน้าที่ธุรการ
 */
export const isTeacherSet3Eligible = (teacher?: Teacher | null): boolean => {
  if (!teacher || isTeacherDeputyDirector(teacher)) return false;
  const category = getTeacherAcademicCategory(teacher);
  return (
    category === "ครูอัตราจ้าง" ||
    category === "พี่เลี้ยงเด็กพิการ" ||
    category === "ครูพี่เลี้ยง" ||
    category === "นักการภารโรง" ||
    category === "เจ้าหน้าที่ธุรการ"
  );
};

/**
 * Committee Set 4: รองผู้อำนวยการสถานศึกษา (2 ท่าน: ประเมินรวมกัน ไม่แยกวิทยฐานะ)
 */
export const isTeacherSet4Eligible = (teacher?: Teacher | null): boolean => {
  if (!teacher) return false;
  return isTeacherDeputyDirector(teacher);
};

export const getTeacherCommitteeSetNumber = (teacher?: Teacher | null): 1 | 2 | 3 | 4 | null => {
  if (!teacher) return null;
  if (isTeacherSet4Eligible(teacher)) return 4;
  if (isTeacherSet1Eligible(teacher)) return 1;
  if (isTeacherSet2Eligible(teacher)) return 2;
  if (isTeacherSet3Eligible(teacher)) return 3;
  return null;
};

export const isTeacherAssignedToCommittee = (teacher?: Teacher | null, committeeMember?: PaCommitteeMember | null): boolean => {
  if (!teacher || !committeeMember) return false;
  const teacherSet = getTeacherCommitteeSetNumber(teacher);
  const commSet = Number(committeeMember.setNumber) || 1;

  if (teacherSet === null || teacherSet !== commSet) {
    return false;
  }

  if (committeeMember.assignedTeacherIds && committeeMember.assignedTeacherIds.length > 0) {
    return committeeMember.assignedTeacherIds.includes(teacher.id);
  }

  return true;
};

